"""This file was generated by LLM

Ask an LLM to label every song's lyrics (sentiment, repetition, theme).

Talks to any OpenAI-compatible chat completions API, configured through the
environment:

    LLM_BASE_URL  the /v1 root of the service (no trailing /chat/completions)
    LLM_MODEL     the model to label with
    LLM_API_KEY   bearer token, if the service wants one

For example, with MetaCentrum / e-INFRA CZ
(https://docs.cerit.io/en/docs/ai-as-a-service/ai-api):

    LLM_BASE_URL=https://llm.ai.e-infra.cz/v1
    LLM_MODEL=gpt-oss-120b
    LLM_API_KEY=<key from chat.ai.e-infra.cz -> Settings -> Account>

Run from this directory, after fetch_lyrics.py has populated raw/lyrics/.
Results land in processed/lyrics_analysis.json and are written after every song, so
the script can be stopped and restarted without losing or redoing work. Songs
that could not be labelled are tracked in processed/lyrics_unlabeled.json (with a
reason), and the raw LLM replies behind any failure are appended to
processed/lyrics_analysis.log for inspection.
"""

import json
import os
import re
import sys
import time

import openai
from openai import OpenAI

# the console is cp1252 on Windows; song/artist names are not
sys.stdout.reconfigure(encoding="utf-8", errors="replace")

BASE_URL = os.environ.get("LLM_BASE_URL", "https://llm.ai.e-infra.cz/v1/").rstrip("/")
MODEL = os.environ.get("LLM_MODEL","gpt-oss-120b") # also deepseek-v4.1-flash, kimi-k3, 
API_KEY = os.environ.get("LLM_API_KEY")

OUT_PATH = os.path.join("processed", "lyrics_analysis.json")
UNLABELED_PATH = os.path.join("processed", "lyrics_unlabeled.json")
LOG_PATH = os.path.join("processed", "lyrics_analysis.log")

# CONFIGURE THIS IF YOU HAVE LIMITED QUOTA
MAX_LYRICS_CHARS = 999999999999
MAX_TOKENS = 999999999999

SENTIMENTS = {"funny", "neutral", "sad"}
YES_NO = {"yes", "no"}
THEMES = {
    "romance",
    "heartbreak",
    "kinship",
    "society",
    "nature",
    "folklore",
    "festivity",
    "other",
}

LANGUAGE_CODE_RE = re.compile(r"^[a-z]{2}$")

# the field the model must answer -> the values it may answer with
# (either a fixed set of allowed values, or a regex the value must match)
FIELDS = {
    "sentiment": SENTIMENTS,
    "repetition_main": YES_NO,
    "high_repetition_chorus": YES_NO,
    "theme": THEMES,
    "language": LANGUAGE_CODE_RE,
}

SYSTEM_PROMPT = (
    "You are a musicologist labelling song lyrics for a dataset. "
    "You answer with a single JSON object and nothing else - no prose, no "
    "markdown fences, no explanation."
)

PROMPT_TEMPLATE = """Read the lyrics below and label the song.

Answer with exactly this JSON object, picking one allowed value per field:

{{
  "sentiment": "funny" | "neutral" | "sad",
  "repetition_main": "yes" | "no",
  "high_repetition_chorus": "yes" | "no",
  "theme": "romance" | "heartbreak" | "kinship" | "society" | "nature" | "folklore" | "festivity" | "other",
  "language": "<ISO 639-1 two-letter code>"
}}

Field meanings:
- sentiment: the overall mood of the lyrics.
- repetition_main: whether the verses (the non-chorus body of the song) repeat
  lines or phrases noticeably.
- high_repetition_chorus: whether the chorus is built on heavy repetition of
  the same line, phrase or hook.
- language: the major/dominant language the lyrics are written in, as its
  ISO 639-1 two-letter code (e.g. "en", "fr", "de", "it").
- theme: the dominant subject of the lyrics; use "other" only when none of the
  named categories fits. Categories description:
    romance (Happy love/passion) – Infatuation, romantic joy, deep affection, sexual attraction.
    heartbreak (Sad love) – Breakups, unrequited love, grief over a romantic partner, longing.
    kinship (Family love) – Parenthood, childhood memories, siblings, platonic loyalty, ancestry.
    society (World/wars) – Anti-war anthems, political commentary, societal struggles, rebellion.
    nature (World/nature) – Landscapes, seasons, the cosmos, environmentalism, wilderness.
    folklore (Mystics/myths) – Folklore, religion, spirituality, supernatural events, legendary figures.
    festivity (Celebration/escapism) – Partying, dancing, leaving worries behind, youth, feeling alive.
    other – Anything that distinctly fails to fit the primary themes.


Song: {song}
Artist: {artist}

Lyrics:
{lyrics}"""

RETRY_PROMPT = (
    "That was not valid. Reply with only the JSON object, using exactly the "
    "five fields and the allowed values."
)


client = OpenAI(
    api_key=API_KEY or "not-needed",
    base_url=BASE_URL,
    timeout=120,
    max_retries=0, # we do our own retry/backoff below, so don't double up
)


def ask(messages, retries=5):
    """Request a chat completion, riding out the service's busy responses."""
    for attempt in range(retries):
        try:
            response = client.chat.completions.create(
                model=MODEL,
                messages=messages,
                temperature=0, # labelling should be reproducible, so leave no room for creativity
                max_tokens=MAX_TOKENS
            )
        except openai.RateLimitError:
            wait = 2 ** attempt
            print(f"  rate limited, retrying in {wait}s...")
            time.sleep(wait)
            continue
        except openai.APIStatusError as exc:
            # these mean the model is busy or the service is having trouble
            if exc.status_code in (500, 502, 503, 504):
                wait = 2 ** attempt
                print(f"  {exc.status_code} from API, retrying in {wait}s...")
                time.sleep(wait)
                continue

            print(f"Error from API: {exc.status_code} {exc.message}")
            return None
        except openai.APIConnectionError as exc:
            print(f"  request failed ({exc}), retrying...")
            time.sleep(2 ** attempt)
            continue

        return response.choices[0].message.content

    print(f"  giving up after {retries} attempts")
    return None


def parse_labels(answer):
    """Pull the JSON object out of the reply and keep it only if it is valid."""
    if not answer:
        return None

    # models like to wrap the object in ```json fences or a sentence
    match = re.search(r"\{.*\}", answer, re.DOTALL)
    if not match:
        return None

    try:
        data = json.loads(match.group(0))
    except json.JSONDecodeError:
        return None

    labels = {}
    for field, allowed in FIELDS.items():
        value = data.get(field)
        if not isinstance(value, str):
            return None

        value = value.strip().lower()
        if isinstance(allowed, set):
            if value not in allowed:
                return None
        elif not allowed.match(value):
            return None

        labels[field] = value

    return labels


def log_raw_answer(key, entry_info, stage, answer):
    """Append a raw LLM reply to the log, so unparseable answers can be inspected."""
    record = {
        "timestamp": time.strftime("%Y-%m-%dT%H:%M:%S"),
        "key": key,
        "stage": stage,
        "answer": answer,
        **entry_info,
    }
    with open(LOG_PATH, 'a', encoding='utf-8') as file:
        file.write(json.dumps(record, ensure_ascii=False) + "\n")


def analyze(song_title, artist_name, lyrics, key, entry_info):
    """Label one song, giving the model a second chance if it rambles."""
    prompt = PROMPT_TEMPLATE.format(
        song=song_title,
        artist=artist_name,
        lyrics=lyrics[:MAX_LYRICS_CHARS],
    )
    messages = [
        {"role": "system", "content": SYSTEM_PROMPT},
        {"role": "user", "content": prompt},
    ]

    answer = ask(messages)
    labels = parse_labels(answer)
    if labels:
        return labels

    if answer is None:
        log_raw_answer(key, entry_info, "no_response", None)
        return None

    # the reply was unusable - show it the mistake and ask once more
    print("  unparseable answer, retrying once")
    log_raw_answer(key, entry_info, "unparseable_first_attempt", answer)
    messages += [
        {"role": "assistant", "content": answer},
        {"role": "user", "content": RETRY_PROMPT},
    ]
    retry_answer = ask(messages)
    labels = parse_labels(retry_answer)
    if not labels:
        log_raw_answer(key, entry_info, "unparseable_retry", retry_answer)
    return labels


def load_results():
    """Pick up where a previous run stopped."""
    if not os.path.exists(OUT_PATH):
        return {}

    with open(OUT_PATH, 'r', encoding='utf-8') as file:
        return json.load(file)


def save_results(results):
    """Write via a temp file so an interrupted run cannot truncate the results."""
    tmp_path = OUT_PATH + ".tmp"
    with open(tmp_path, 'w', encoding='utf-8') as file:
        json.dump(results, file, ensure_ascii=False, indent=2, sort_keys=True)

    os.replace(tmp_path, OUT_PATH)


def load_unlabeled():
    """Pick up the set of songs that failed on a previous run."""
    if not os.path.exists(UNLABELED_PATH):
        return {}

    with open(UNLABELED_PATH, 'r', encoding='utf-8') as file:
        return json.load(file)


def save_unlabeled(unlabeled):
    """Write via a temp file so an interrupted run cannot truncate the results."""
    tmp_path = UNLABELED_PATH + ".tmp"
    with open(tmp_path, 'w', encoding='utf-8') as file:
        json.dump(unlabeled, file, ensure_ascii=False, indent=2, sort_keys=True)

    os.replace(tmp_path, UNLABELED_PATH)


if __name__ == "__main__":
    if not BASE_URL:
        sys.exit("Set LLM_BASE_URL to the /v1 root of an OpenAI-compatible API")

    if not MODEL:
        sys.exit("Set LLM_MODEL to the model you want to label with")

    print(f"Using model {MODEL} at {BASE_URL}")

    os.makedirs("processed", exist_ok=True)

    with open("dataset_info.json", 'r', encoding='utf-8') as file:
        dataset_info = json.load(file)

    results = load_results()
    unlabeled = load_unlabeled()

    def mark_unlabeled(key, reason, entry_info):
        unlabeled[key] = {"reason": reason, **entry_info}
        save_unlabeled(unlabeled)

    for year, year_data in dataset_info.items():
        print(f"Processing {year}")

        with open(year_data["path"], 'r', encoding='utf-8') as file:
            entries = json.load(file)

        for country, entry in entries.items():
            song_title = entry.get("song")
            artist_name = entry.get("artist")

            if not (song_title and artist_name):
                continue

            key = f"{country.replace(' ', '_')}_{year}"
            if key in results:
                continue

            entry_info = {
                "country": country,
                "year": year,
                "artist": artist_name,
                "song": song_title,
            }

            # fetch_lyrics.py names the lyrics files the same way
            lyrics_path = os.path.join("raw", "lyrics", f"{key}.txt")
            if not os.path.exists(lyrics_path):
                print(f"  no lyrics on disk for {country} {year}: {song_title}")
                mark_unlabeled(key, "no_lyrics_on_disk", entry_info)
                continue

            with open(lyrics_path, 'r', encoding='utf-8') as file:
                lyrics = file.read().strip()

            if not lyrics:
                print(f"  empty lyrics for {country} {year}: {song_title}")
                mark_unlabeled(key, "empty_lyrics", entry_info)
                continue

            labels = analyze(song_title, artist_name, lyrics, key, entry_info)
            if labels is None:
                print(f"  could not label {country} {year}: {song_title}")
                mark_unlabeled(key, "unparseable_llm_response", entry_info)
                continue

            results[key] = {
                **entry_info,
                **labels,
            }
            save_results(results)

            # a song that failed on a previous run and now succeeded is no longer unlabeled
            if unlabeled.pop(key, None) is not None:
                save_unlabeled(unlabeled)

            print(f"  {country}: {song_title} -> {labels['sentiment']}, {labels['theme']}")
            time.sleep(0.5)

    print(f"\nLabelled {len(results)} songs -> {OUT_PATH}")
    if unlabeled:
        print(f"Could not label {len(unlabeled)} songs -> {UNLABELED_PATH} (raw replies in {LOG_PATH})")
